import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws synchronously from register naming the tool when a static inputSchema is invalid', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'invalid_schema_tool',
          description: 'Declares an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {query: {type: 'not-a-type'}},
          },
        },
        async () => 'ok'
      )
    ).toThrow(/invalid_schema_tool/);
  });

  it('caches compiled validators for function-valued tool schemas by schema object reference', async () => {
    const trackedSchema = (propertyName: string) => {
      let reads = 0;
      const schema: Record<string, unknown> = {type: 'object'};
      Object.defineProperty(schema, 'properties', {
        enumerable: true,
        get() {
          reads += 1;
          return {[propertyName]: {type: 'string'}};
        },
      });
      return {schema, readCount: () => reads};
    };
    const trackerA = trackedSchema('city');
    let currentSchema = trackerA.schema;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Dynamic schema tool',
        inputSchema: currentSchema,
      }),
      async () => 'ok'
    );

    const observations = {
      compiledAOnFirstUse: false,
      reusedAOnSecondUse: false,
      compiledBOnSwitch: false,
      reusedAAfterSwitch: false,
    };
    await registry.execute('dynamic_lookup', {city: 'Paris'});
    const initialAReads = trackerA.readCount();
    observations.compiledAOnFirstUse = initialAReads > 0;
    await registry.execute('dynamic_lookup', {city: 'London'});
    observations.reusedAOnSecondUse = trackerA.readCount() === initialAReads;
    const trackerB = trackedSchema('zip');
    currentSchema = trackerB.schema;
    await registry.execute('dynamic_lookup', {zip: '75001'});
    observations.compiledBOnSwitch = trackerB.readCount() > 0;
    currentSchema = trackerA.schema;
    await registry.execute('dynamic_lookup', {city: 'Berlin'});
    observations.reusedAAfterSwitch = trackerA.readCount() === initialAReads;

    expect(observations).toEqual({
      compiledAOnFirstUse: true,
      reusedAOnSecondUse: true,
      compiledBOnSwitch: true,
      reusedAAfterSwitch: true,
    });
  });

  it('rejects invalid input before invoking the executor without leaking offending values to result or logs', async () => {
    const logLines: string[] = [];
    const appendLog = (category: string, message: string, fields?: Record<string, unknown>) => {
      logLines.push(JSON.stringify({category, message, fields}));
    };
    const spyLogger: Logger = {
      debug: appendLog,
      info: appendLog,
      warn: appendLog,
      error: appendLog,
    };
    setLogger(spyLogger);

    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {
        name: 'create_booking',
        description: 'Creates a room booking',
        inputSchema: {
          type: 'object',
          properties: {
            guest: {
              type: 'object',
              properties: {
                name: {type: 'string'},
                nights: {type: 'integer'},
              },
              required: ['name'],
            },
            tier: {type: 'string', enum: ['standard', 'suite']},
          },
          required: ['guest', 'tier'],
        },
      },
      async () => {
        calls += 1;
        return 'booked';
      }
    );

    const missingResponse = await registry.execute('create_booking', {guest: {}, tier: 'standard'});
    const wrongTypeResponse = await registry.execute('create_booking', {
      guest: {name: 'Ada', nights: 'secret-nights'},
      tier: 'standard',
    });
    const wrongEnumResponse = await registry.execute('create_booking', {
      guest: {name: 'Ada', nights: 2},
      tier: 'secret-tier',
    });

    const missingNamesFieldAndConstraint =
      missingResponse.result.includes('guest.name') && /required/i.test(missingResponse.result);
    const wrongTypeNamesFieldAndType =
      wrongTypeResponse.result.includes('guest.nights') && wrongTypeResponse.result.includes('integer');
    const wrongEnumNamesFieldAndConstraint =
      wrongEnumResponse.result.includes('tier') && /allowed|enum|one of/i.test(wrongEnumResponse.result);
    const resultLeaksSecret =
      wrongTypeResponse.result.includes('secret-nights') || wrongEnumResponse.result.includes('secret-tier');
    const logLeaksSecret = logLines.some(
      line => line.includes('secret-nights') || line.includes('secret-tier')
    );

    expect({
      calls,
      missingNamesFieldAndConstraint,
      wrongTypeNamesFieldAndType,
      wrongEnumNamesFieldAndConstraint,
      resultLeaksSecret,
      logLeaksSecret,
    }).toEqual({
      calls: 0,
      missingNamesFieldAndConstraint: true,
      wrongTypeNamesFieldAndType: true,
      wrongEnumNamesFieldAndConstraint: true,
      resultLeaksSecret: false,
      logLeaksSecret: false,
    });
  });
});

