    this.dynamicValidators.set(resolved.inputSchema, compiled);
    return compiled;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validate =
      typeof definition === 'function' ? undefined : compileToolSchema(this.ajv, resolved.name, resolved.inputSchema);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input, returning a ToolResponse on rejection; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.resolveValidator(tool);
    if (!validate(input)) {
      const failures = describeValidationFailures(validate.errors ?? []);
      log.warn('tool', 'input validation failed', {
        name,
        failures: failures.map(failure => ({path: failure.fieldPath, constraint: failure.keyword})),
      });
      return {result: formatRejectionMessage(name, failures)};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

interface AjvErrorLike {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: Record<string, unknown>;
  message?: string;
}

interface ValidationFailure {
  fieldPath: string;
  keyword: string;
  summary: string;
}

function compileToolSchema(ajv: AjvInstance, toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${errorMessage}`, {cause: error});
  }
}

function formatRejectionMessage(toolName: string, failures: ValidationFailure[]): string {
  if (failures.length === 0) return `Input validation failed for tool "${toolName}"`;
  const details = failures.map(failure => failure.summary).join('; ');
  return `Input validation failed for tool "${toolName}": ${details}`;
}

function describeValidationFailures(schemaErrors: AjvErrorLike[]): ValidationFailure[] {
  return schemaErrors.map(describeAjvError);
}

function describeAjvError(schemaError: AjvErrorLike): ValidationFailure {
  const summary = formatKeywordFailure(schemaError);
  const fieldPath = formatFailurePath(schemaError);
  return {fieldPath, keyword: schemaError.keyword, summary};
}

function formatKeywordFailure(schemaError: AjvErrorLike): string {
  if (schemaError.keyword === 'required') return formatRequiredFailure(schemaError);
  if (schemaError.keyword === 'type') return formatTypeFailure(schemaError);
  if (schemaError.keyword === 'enum') return formatEnumFailure(schemaError);
  const fieldPath = formatFieldPath(schemaError);
  return `${fieldPath}: ${schemaError.message ?? `failed ${schemaError.keyword} constraint`}`;
}

function formatFailurePath(schemaError: AjvErrorLike): string {
  if (schemaError.keyword === 'required') return formatRequiredPath(schemaError);
  return formatFieldPath(schemaError);
}

function formatRequiredFailure(schemaError: AjvErrorLike): string {
  const targetPath = formatRequiredPath(schemaError);
  return `missing required property '${targetPath}'`;
}

function formatTypeFailure(schemaError: AjvErrorLike): string {
  const fieldPath = formatFieldPath(schemaError);
  const rawType = schemaError.params.type;
  const expectedType = Array.isArray(rawType) ? rawType.join(' | ') : String(rawType ?? 'expected type');
  return `property '${fieldPath}' must be of type ${expectedType}`;
}

function formatEnumFailure(schemaError: AjvErrorLike): string {
  const fieldPath = formatFieldPath(schemaError);
  const allowed = schemaError.params.allowedValues;
  if (!Array.isArray(allowed)) return `property '${fieldPath}' must match one of the allowed values`;
  const choices = allowed.map(choice => JSON.stringify(choice)).join(', ');
  return `property '${fieldPath}' must be one of the allowed values (${choices})`;
}

function formatRequiredPath(schemaError: AjvErrorLike): string {
  const basePath = formatFieldPath(schemaError);
  const missingProperty =
    typeof schemaError.params.missingProperty === 'string' ? schemaError.params.missingProperty : '';
  if (!missingProperty) return basePath;
  return basePath === 'input' ? missingProperty : `${basePath}.${missingProperty}`;
}

function formatFieldPath(schemaError: AjvErrorLike): string {
  const rawPath = schemaError.instancePath ?? schemaError.dataPath ?? '';
  if (!rawPath) return 'input';
  const normalized = rawPath.replace(/^[/.]+/, '').replace(/\//g, '.');
  return normalized || 'input';
}

